// 활성 선수 필터
// MVP: 전원 수집 (30명) 또는 tier 기반 필터
// 설정: maxTier를 변경하여 수집 범위 조절
const maxTier = 4; // 1=Tier1만(5명), 2=Tier1-2(16명), 3=Tier1-3(23명), 4=전원(30명)

const players = $input.all().map(item => item.json);
const filtered = players.filter(p => p.tier <= maxTier);

return filtered.map(player => ({ json: player }));

// ============================================
// 대상 선수 선택
// mode에 따라 필터링 전략 변경
// ============================================

// ── 설정 ──────────────────────────────────
// 'manual'       : selectedIds 목록에 있는 선수만 실행
// 'recent_match' : 최근 24시간 내 경기가 있는 선수만 (TODO: FotMob API 연동)
// 'all'          : 전체 통과 (활성 선수 필터 결과 그대로)
const mode = 'manual';

// manual 모드: 실행할 선수 FotMob ID 목록
// 레지스트리의 id 필드와 매칭
const selectedIds = [
  1044299,  // 오현규 (Besiktas)
  828159,   // 김민재 (Bayern Munich)
  940976,   // 이강인 (PSG)
];
// ───────────────────────────────────────────

const players = $input.all().map(item => item.json);

if (mode === 'all') {
  return players.map(p => ({ json: p }));
}

if (mode === 'manual') {
  const idSet = new Set(selectedIds);
  const filtered = players.filter(p => idSet.has(p.id));

  if (filtered.length === 0) {
    throw new Error(
      `선택된 선수가 없습니다. selectedIds: [${selectedIds.join(', ')}]\n` +
      `사용 가능한 ID: ${players.map(p => p.id + '(' + p.nameKr + ')').join(', ')}`
    );
  }

  return filtered.map(p => ({ json: p }));
}

if (mode === 'recent_match') {
  // TODO: FotMob API 연동
  // 각 선수의 최근 경기 일시를 조회하여 24시간 이내인 경우만 통과
  // 구현 예시:
  //
  // const cutoff = new Date();
  // cutoff.setHours(cutoff.getHours() - 24);
  //
  // const results = [];
  // for (const player of players) {
  //   const res = await fetch(`https://www.fotmob.com/api/playerData?id=${player.id}`);
  //   const data = await res.json();
  //   const lastMatch = data.recentMatches?.[0];
  //   if (lastMatch) {
  //     const matchDate = new Date(lastMatch.matchDate);
  //     if (matchDate >= cutoff) {
  //       results.push({ json: { ...player, lastMatch } });
  //     }
  //   }
  //   await new Promise(r => setTimeout(r, 500)); // rate limit
  // }
  // return results.length > 0 ? results : []; // 빈 배열이면 워크플로우 자동 중단

  // 현재는 미구현 → 전체 통과 (fallback)
  console.log('[대상 선수 선택] recent_match 모드 미구현 → 전체 통과');
  return players.map(p => ({ json: p }));
}

throw new Error(`알 수 없는 mode: "${mode}". 사용 가능: manual, recent_match, all`);

// ============================================
// GPT 프롬프트 빌드 (v4 - 실제 스탯 데이터 통합)
// 초회: 수집 데이터 + 스탯 기반 기사 생성
// 재시도: QA 피드백 반영하여 재생성
// ============================================

const input = $input.first().json;

// QA 재시도 감지
const isQaRetry = !!input.qaFeedback;

let player, qaAttempt, qaFeedback;

if (isQaRetry) {
  // QA 통과? False에서 루프백
  player = input.player;
  qaAttempt = (input.qaAttempt || 0) + 1;
  qaFeedback = input.qaFeedback;
} else {
  // 스탯 데이터 병합에서 최초 진입
  player = input;
  qaAttempt = 1;
  qaFeedback = null;
}

const { webSearchSummary, newsSources, redditSources } = player.collected;

// 뉴스 소스 텍스트 생성
const newsSourcesText = newsSources.map((n, i) =>
  `[뉴스${i + 1}] ${n.title} (${n.url})`
).join('\n');

// Reddit 소스 텍스트 생성
const redditSourcesText = redditSources.map((r, i) =>
  `[Reddit${i + 1}] ${r.title} (${r.url})`
).join('\n');

const systemPrompt = `너는 한국 축구 전문 AI 기자이다. 해외파 선수에 대한 현지 여론과 뉴스를 분석하여 한국어 기사를 작성한다.

출력 형식은 반드시 아래 JSON 스키마를 따라야 한다:
{
  "title": "기사 제목 (한글, 핵심 수치/반응 포함, 인용 반응 또는 핵심 수치 + 선수명)",
  "subtitle": "부제목 (경기/리그 정보)",
  "summary": "1-2문장 요약 (핵심 수치 + 영문 반응 인용 포함)",
  "content": "마크다운 기사 본문 (3개 섹션: ## 경기 요약, ## 해외 현지 반응 (AI 요약), ## AI 분석 요약)",
  "matchInfo": "리그/대회명 | 경기 스코어",
  "tags": ["선수이름한글", "팀이름한글", ...],
  "evidence": {
    "charts": [
      {
        "id": "고유-kebab-id",
        "title": "차트 제목 (한글)",
        "type": "bar|radar|line|pie",
        "data": [/* 차트 타입에 맞는 데이터 */],
        "dataKeys": ["키1", "키2"],
        "colors": ["#d90828", "#94a3b8"]
      }
    ],
    "dataRows": [
      {
        "label": "지표명 (한글)",
        "value": "수치 또는 텍스트",
        "interpretation": "해석 (한글, 2문장 이상, 30자 이상, 비교/맥락 포함)",
        "source": "출처명 (실제 존재하는 매체/데이터소스)"
      }
    ]
  }
}

=== 차트 데이터 구조 규칙 ===
1. bar 차트: data 각 항목에 { name: "항목명(한글)", 키1: 숫자, 키2: 숫자 }
2. radar 차트: data 각 항목에 { stat: "능력명(한글)", value: 0~100 숫자 }
3. line 차트: data 각 항목에 { match/시점키: "라벨", 데이터키: 숫자 }
4. pie 차트: data 각 항목에 { name: "카테고리(한글)", value: 숫자, fill: "#hex색상" }
   - 감성 분석: 긍정(#22c55e), 중립(#94a3b8), 부정(#ef4444) 사용, value 합계 = 100

=== 기사 작성 규칙 ===
1. content는 반드시 3개 섹션: ## 경기 요약, ## 해외 현지 반응 (AI 요약), ## AI 분석 요약
2. 해외 현지 반응 섹션에서 ### Reddit r/{sub} 반응, ### 현지 매체 등 하위 섹션 사용
   - 반드시 수집 데이터의 실제 인용만 사용 (출처 조작 금지)
3. evidence.charts: 3-4개, 최소 2종류 이상 차트 타입, 감성 pie chart 필수 포함
4. evidence.dataRows: 4-5개, 각 interpretation 30자 이상, 비교/맥락 포함
5. colors에는 브랜드 컬러 #d90828(빨강)과 #94a3b8(회색) 사용
6. 한글 일관성: 선수명 한글, 영문 정확(FotMob 이름 아닌 실제 표기법 사용)
7. 태그에 반드시 선수한글명, 팀한글명 포함
8. 각 섹션 최소 2문단 이상, content 전체 500자 이상
9. 비축구 콘텐츠 필터링, 다국어 원문 한국어 번역
10. 수집 데이터가 부족하면 무리하게 만들지 말고 있는 정보만으로 작성

=== 실제 스탯 데이터 활용 규칙 (중요) ===
아래에 FotMob 기반 실제 선수 스탯이 제공될 수 있다. 제공된 경우:
1. charts의 bar/radar/line 차트에 반드시 실제 수치를 사용할 것
2. dataRows의 value에 반드시 실제 수치를 사용할 것
3. 데이터를 임의로 만들거나 추측하지 말 것
4. source에 "FotMob" 또는 실제 데이터 출처를 명시할 것
5. 최근 경기 데이터가 있으면 경기별 성과 bar 차트 생성
6. 포지션별 주요 지표로 radar 차트 생성`;

let userPrompt = `선수: ${player.nameKr} (${player.fotmobName})
팀: ${player.team || '정보없음'}
리그: ${player.league || '정보없음'}

=== AI 웹 검색으로 수집된 현지 반응 ===
${webSearchSummary || '(수집된 데이터 없음)'}

=== 출처: 해외 뉴스 (${newsSources.length}건) ===
${newsSourcesText || '(수집된 뉴스 없음)'}

=== 출처: Reddit (${redditSources.length}건) ===
${redditSourcesText || '(수집된 Reddit 반응 없음)'}`;

// ====== 실제 스탯 데이터 추가 ======
if (player.statsData && player.statsData.hasData) {
  const { profile, weeklyStats, recentMatches } = player.statsData;

  userPrompt += '\n\n=== 실제 선수 스탯 데이터 (FotMob 기반) ===';
  userPrompt += '\n아래 데이터는 FotMob에서 수집된 실제 데이터이다. 차트와 dataRows 생성 시 반드시 이 데이터를 기반으로 해야 한다.\n';

  if (profile) {
    userPrompt += '\n--- 선수 프로필 ---';
    userPrompt += `\n시장 가치: ${profile.market_value || 'N/A'}`;
    userPrompt += `\n포지션: ${profile.position || 'N/A'}`;
    userPrompt += `\n시즌: ${profile.season || 'N/A'}`;
    userPrompt += `\n출전 경기: ${profile.matches || 'N/A'} (선발: ${profile.started || 'N/A'})`;
    userPrompt += `\n출전 시간: ${profile.minutes_played || 'N/A'}분`;
    userPrompt += `\n골: ${profile.goals || 0} (xG: ${profile.attack_expected_goals || 'N/A'})`;
    userPrompt += `\n어시스트: ${profile.assists || 0} (xA: ${profile.passing_expected_assists || 'N/A'})`;
    userPrompt += `\n평균 평점: ${profile.rating || 'N/A'} (백분위: ${profile.rating_percentile || 'N/A'})`;

    // 포지션별 세부 지표
    const pos = (profile.position || '').toLowerCase();

    if (pos.includes('forward') || pos.includes('striker') || pos.includes('winger') || pos.includes('att')) {
      userPrompt += '\n\n--- 공격 지표 ---';
      userPrompt += `\n슈팅: ${profile.attack_shots || 0} (유효슈팅: ${profile.attack_shots_on_target || 0})`;
      userPrompt += `\n슈팅 정확도: ${profile.attack_shooting_accuracy || 'N/A'}%`;
      userPrompt += `\n골 전환율: ${profile.attack_conversion_rate || 'N/A'}%`;
      userPrompt += `\nxG 차이: ${profile.attack_xg_difference || 'N/A'} (실제골 - xG)`;
      userPrompt += `\n빅찬스 실축: ${profile.attack_big_chances_missed || 0}`;
      userPrompt += `\n드리블 성공: ${profile.attack_dribbles_succeeded || 0} (${profile.attack_dribble_success_rate || 'N/A'}%)`;
      userPrompt += `\n박스 내 터치: ${profile.attack_touches_in_box || 0}`;
    }

    if (pos.includes('defender') || pos.includes('back') || pos.includes('cb')) {
      userPrompt += '\n\n--- 수비 지표 ---';
      userPrompt += `\n태클: ${profile.defense_tackles || 0} (성공: ${profile.defense_tackles_successful || 0}, ${profile.defense_tackle_success_rate || 'N/A'}%)`;
      userPrompt += `\n인터셉트: ${profile.defense_interceptions || 0}`;
      userPrompt += `\n클리어링: ${profile.defense_clearances || 0}`;
      userPrompt += `\n블록: ${profile.defense_blocked_shots || 0}`;
      userPrompt += `\n공중볼 성공: ${profile.defense_aerials_won || 0} (${profile.defense_aerial_success_rate || 'N/A'}%)`;
      userPrompt += `\n듀얼 성공률: ${profile.defense_duel_success_rate || 'N/A'}%`;
      userPrompt += `\n지상 듀얼: ${profile.defense_ground_duels_won || 0} (${profile.defense_ground_duel_success_rate || 'N/A'}%)`;
      userPrompt += `\n볼 회수: ${profile.defense_recoveries || 0}`;
      userPrompt += `\n드리블 허용: ${profile.defense_dribbled_past || 0}`;
    }

    if (pos.includes('midfielder') || pos.includes('mid')) {
      userPrompt += '\n\n--- 패스/창의력 지표 ---';
      userPrompt += `\n키패스: ${profile.passing_key_passes || 0}`;
      userPrompt += `\n찬스 창출: ${profile.passing_chances_created || 0}`;
      userPrompt += `\n패스 성공: ${profile.passing_successful_passes || 0} (${profile.passing_pass_accuracy || 'N/A'}%)`;
      userPrompt += `\n롱볼 성공: ${profile.passing_long_balls_accurate || 0} (${profile.passing_long_ball_accuracy || 'N/A'}%)`;
      userPrompt += `\n크로스 성공: ${profile.passing_crosses_accurate || 0} (${profile.passing_cross_accuracy || 'N/A'}%)`;
    }

    // 공통 지표
    userPrompt += '\n\n--- 공통 지표 ---';
    userPrompt += `\n패스 성공률: ${profile.passing_pass_accuracy || 'N/A'}%`;
    userPrompt += `\n경고: ${profile.discipline_yellow_cards || 0} / 퇴장: ${profile.discipline_red_cards || 0}`;
    userPrompt += `\n파울 유도: ${profile.possession_fouls_won || 0} / 파울 범함: ${profile.defense_fouls_committed || 0}`;
    userPrompt += `\n점유 터치: ${profile.possession_touches || 0}`;
    userPrompt += `\n볼 빼앗김: ${profile.possession_dispossessed || 0}`;
  }

  if (weeklyStats) {
    userPrompt += '\n\n--- 주간 스탯 요약 ---';
    userPrompt += `\n수집일: ${weeklyStats.collection_date || 'N/A'}`;
    userPrompt += `\n시즌 경기: ${weeklyStats.season_matches || 'N/A'}`;
    userPrompt += `\n시즌 골: ${weeklyStats.season_goals || 0}`;
    userPrompt += `\n시즌 어시스트: ${weeklyStats.season_assists || 0}`;
    userPrompt += `\n시즌 평균 평점: ${weeklyStats.season_avg_rating || 'N/A'}`;
    userPrompt += `\n부상 여부: ${weeklyStats.is_injured || 'No'}`;
    if (weeklyStats.injury_status) {
      userPrompt += `\n부상 상태: ${weeklyStats.injury_status}`;
    }
    if (weeklyStats.contract_end) {
      userPrompt += `\n계약 만료: ${weeklyStats.contract_end}`;
    }
  }

  if (recentMatches && recentMatches.length > 0) {
    userPrompt += '\n\n--- 최근 경기 (bar 차트용 실제 데이터) ---';
    for (const match of recentMatches) {
      const homeAway = match.is_home ? '(홈)' : '(원정)';
      userPrompt += `\n${match.date} vs ${match.opponent} ${homeAway}: ${match.result}`;
      userPrompt += ` | ${match.minutes}분 | 골:${match.goals} 어시:${match.assists}`;
      if (match.rating) userPrompt += ` | 평점:${match.rating}`;
      if (match.is_motm) userPrompt += ' ★MOTM';
    }
  }

  userPrompt += '\n\n=== 중요: 차트/dataRows 생성 시 위 실제 데이터를 반드시 사용할 것. 데이터를 임의로 만들지 말 것. ===';
} else {
  userPrompt += '\n\n※ 실제 스탯 데이터 미제공 — 수집된 뉴스/반응 내 언급된 수치만 사용할 것.';
}

userPrompt += '\n\n위 데이터를 기반으로 기사 JSON을 생성해줘.';

// QA 재시도 시 피드백 추가
if (qaFeedback) {
  userPrompt += `\n\n=== QA 검증 피드백 (${qaAttempt - 1}차 생성 결과) ===
이전 생성 기사에서 다음 품질 이슈가 발견되었다. 모든 이슈를 수정하여 다시 생성해줘:

${qaFeedback}

특히 주의:
- 각 섹션(경기 요약, 해외 현지 반응, AI 분석 요약)은 반드시 2문단 이상 작성
- 감성 분석 pie chart 반드시 포함
- charts 최소 3개, 최소 2가지 타입 사용
- dataRows의 interpretation은 30자 이상
- 실제 스탯 데이터가 제공된 경우 반드시 활용`;
}

return [{
  json: {
    player,
    gptRequest: {
      model: 'gpt-4o',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      response_format: { type: 'json_object' },
      temperature: qaFeedback ? 0.5 : 0.7,
      max_tokens: 8192,
    },
    systemPrompt,
    userPrompt,
    collectedData: { newsSources, redditSources },
    qaAttempt,
  },
}];

// ============================================
// 응답 파싱 (v2 - qaAttempt 전달)
// GPT 응답 -> Article 스키마 매핑
// ============================================

const input = $input.first().json;
const { player, systemPrompt, userPrompt, collectedData, qaAttempt } = $('GPT 프롬프트 빌드').first().json;

// GPT 응답 파싱
let gptResponse;
try {
  const rawContent = input.choices[0].message.content;
  gptResponse = JSON.parse(rawContent);
} catch (error) {
  gptResponse = {
    title: `${player.nameKr} 최신 소식`,
    subtitle: '',
    summary: 'GPT 응답 파싱 실패',
    content: '## 경기 요약\n\n정보를 처리하는 중 오류가 발생했습니다.\n\n## 해외 현지 반응 (AI 요약)\n\n-\n\n## AI 분석 요약\n\n-',
    tags: [player.nameKr],
    evidence: { charts: [], dataRows: [] },
  };
}

// Article 스키마로 매핑
const evidence = gptResponse.evidence || { charts: [], dataRows: [] };

const validChartTypes = ['bar', 'radar', 'line', 'pie'];
const charts = (evidence.charts || []).filter(chart =>
  chart.id && chart.title && validChartTypes.includes(chart.type) &&
  Array.isArray(chart.data) && chart.data.length > 0 &&
  Array.isArray(chart.dataKeys) && chart.dataKeys.length > 0 &&
  Array.isArray(chart.colors) && chart.colors.length > 0
).map(chart => ({
  id: chart.id,
  title: chart.title,
  type: chart.type,
  data: chart.data,
  dataKeys: chart.dataKeys,
  colors: chart.colors,
}));

const dataRows = (evidence.dataRows || []).filter(row =>
  row.label && row.value !== undefined && row.interpretation
).map(row => ({
  label: row.label,
  value: row.value,
  interpretation: row.interpretation,
  source: row.source || '',
}));

const article = {
  id: `opinion-${player.nameKr}-${Date.now()}`,
  title: gptResponse.title || `${player.nameKr} 최신 소식`,
  subtitle: gptResponse.subtitle || '',
  summary: gptResponse.summary || '',
  content: gptResponse.content || '',
  playerName: player.fotmobName,
  playerNameKr: player.nameKr,
  team: player.team || '',
  league: player.league || '',
  matchInfo: gptResponse.matchInfo || gptResponse.subtitle || '',
  publishedAt: new Date().toISOString(),
  thumbnailUrl: '',
  tags: Array.isArray(gptResponse.tags) ? gptResponse.tags : [player.nameKr],
  evidence: { charts, dataRows },
};

return [{ json: { article, player, systemPrompt, userPrompt, collectedData, qaAttempt } }];

// ============================================
// QA 검증 (v3 - 워크플로우 레벨 재시도 루프 지원)
// 4-Agent QA 검증 → qaPass로 루프/통과 결정
// 실패 시 QA 피드백 포함하여 GPT 프롬프트 빌드로 루프
// ============================================

let { article, player, systemPrompt, userPrompt, collectedData, qaAttempt } = $input.first().json;
qaAttempt = qaAttempt || 1;

const MAX_QA_RETRIES = 3;

// ========== QA Agent 1: DataValidator ==========
function runDataValidator(art) {
  const issues = [];

  for (const row of (art.evidence?.dataRows || [])) {
    if (!row.source || row.source.trim() === '') {
      issues.push({ level: 'warning', msg: `dataRow "${row.label}" 출처 누락` });
    }
  }

  for (const chart of (art.evidence?.charts || [])) {
    if (chart.type === 'pie') {
      const sum = chart.data.reduce((acc, d) => acc + (d.value || 0), 0);
      if (sum !== 100) {
        issues.push({ level: 'critical', msg: `pie chart "${chart.title}" 합계 ${sum} ≠ 100` });
      }
    }
  }

  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  if (new Date(art.publishedAt) < sevenDaysAgo) {
    issues.push({ level: 'warning', msg: 'publishedAt이 7일 이전' });
  }

  return issues;
}

// ========== QA Agent 2: KoreanQA ==========
function runKoreanQA(art, playerInfo) {
  const issues = [];
  const content = art.content || '';

  const requiredSections = ['## 경기 요약', '## 해외 현지 반응 (AI 요약)', '## AI 분석 요약'];
  for (const sec of requiredSections) {
    if (!content.includes(sec)) {
      issues.push({ level: 'critical', msg: `섹션 누락: ${sec}` });
    }
  }

  if (!content.includes(playerInfo.nameKr) && !art.title.includes(playerInfo.nameKr)) {
    issues.push({ level: 'warning', msg: `선수 한글명 "${playerInfo.nameKr}" 미포함` });
  }

  if (!art.tags || !art.tags.includes(playerInfo.nameKr)) {
    issues.push({ level: 'warning', msg: `태그에 선수한글명 "${playerInfo.nameKr}" 누락` });
  }

  const brokenPattern = /[\ufffd\u0000-\u0008\u000b\u000c\u000e-\u001f]/;
  if (brokenPattern.test(content)) {
    issues.push({ level: 'critical', msg: '인코딩 깨짐 감지' });
  }

  return issues;
}

// ========== QA Agent 3: SchemaValidator ==========
function runSchemaValidator(art) {
  const issues = [];

  const requiredFields = ['id', 'title', 'subtitle', 'summary', 'content', 'playerName', 'playerNameKr', 'team', 'league', 'matchInfo', 'publishedAt', 'tags', 'evidence'];
  for (const field of requiredFields) {
    if (art[field] === undefined || art[field] === null) {
      issues.push({ level: 'critical', msg: `필수필드 누락: ${field}` });
    }
  }

  const charts = art.evidence?.charts || [];
  if (charts.length < 1) {
    issues.push({ level: 'critical', msg: 'charts 없음 (최소 1개 필요)' });
  } else if (charts.length > 4) {
    issues.push({ level: 'warning', msg: `charts ${charts.length}개 (권장 1-4개)` });
  }

  for (const chart of charts) {
    if (!chart.id || !chart.title || !chart.type) {
      issues.push({ level: 'critical', msg: '차트 필수필드 누락' });
    }
    if (!Array.isArray(chart.data) || chart.data.length === 0) {
      issues.push({ level: 'critical', msg: `차트 data 비어있음: ${chart.id}` });
    }
    if (chart.type === 'pie') {
      for (const d of (chart.data || [])) {
        if (!d.fill) issues.push({ level: 'warning', msg: `pie 항목 fill 색상 누락: ${d.name}` });
      }
    }
  }

  const dataRows = art.evidence?.dataRows || [];
  if (dataRows.length < 2) {
    issues.push({ level: 'critical', msg: `dataRows ${dataRows.length}개 (최소 2개 필요)` });
  } else if (dataRows.length > 5) {
    issues.push({ level: 'info', msg: `dataRows ${dataRows.length}개 (권장 2-5개)` });
  }

  return issues;
}

// ========== QA Agent 4: QualityReviewer ==========
function runQualityReviewer(art) {
  const issues = [];
  const content = art.content || '';

  if (content.length < 500) {
    issues.push({ level: 'critical', msg: `content 길이 부족: ${content.length}자 (최소 500자)` });
  }

  const sections = content.split(/## /);
  for (const sec of sections.slice(1)) {
    const paragraphs = sec.split('\n\n').filter(p => p.trim().length > 0);
    if (paragraphs.length < 2) {
      const secName = sec.split('\n')[0].trim();
      issues.push({ level: 'warning', msg: `섹션 "${secName}" 문단 부족 (${paragraphs.length}개)` });
    }
  }

  const charts = art.evidence?.charts || [];
  if (!charts.some(c => c.type === 'pie')) {
    issues.push({ level: 'critical', msg: '감성 pie chart 없음' });
  }

  const chartTypes = new Set(charts.map(c => c.type));
  if (chartTypes.size < 2 && charts.length > 0) {
    issues.push({ level: 'warning', msg: `차트 타입 다양성 부족 (${chartTypes.size}종)` });
  }

  const hasKfnRed = charts.some(c => (c.colors || []).includes('#d90828'));
  if (!hasKfnRed && charts.length > 0) {
    issues.push({ level: 'info', msg: '브랜드 컬러 #d90828 미사용' });
  }

  for (const row of (art.evidence?.dataRows || [])) {
    if ((row.interpretation || '').length < 30) {
      issues.push({ level: 'warning', msg: `dataRow "${row.label}" interpretation ${(row.interpretation || '').length}자 (최소 30자)` });
    }
  }

  return issues;
}

// ========== 채점 ==========
function calcScore(issues) {
  let score = 100;
  for (const issue of issues) {
    if (issue.level === 'critical') score -= 30;
    else if (issue.level === 'warning') score -= 10;
    else if (issue.level === 'info') score -= 2;
  }
  return Math.max(0, score);
}

// ========== 자동 수정 ==========
function autoFix(art) {
  for (const chart of (art.evidence?.charts || [])) {
    if (chart.type === 'pie') {
      const sum = chart.data.reduce((acc, d) => acc + (d.value || 0), 0);
      if (sum !== 100 && sum > 0) {
        chart.data = chart.data.map(d => ({ ...d, value: Math.round((d.value / sum) * 100) }));
        const newSum = chart.data.reduce((acc, d) => acc + d.value, 0);
        if (newSum !== 100) chart.data[0].value += (100 - newSum);
      }
    }
  }
  return art;
}

// ========== QA 실행 ==========
article = autoFix(article);

const agents = [
  { name: 'DataValidator', issues: runDataValidator(article) },
  { name: 'KoreanQA', issues: runKoreanQA(article, player) },
  { name: 'SchemaValidator', issues: runSchemaValidator(article) },
  { name: 'QualityReviewer', issues: runQualityReviewer(article) },
];

const allIssues = agents.flatMap(a => a.issues.map(i => ({ ...i, agent: a.name })));
const scores = agents.map(a => ({ name: a.name, score: calcScore(a.issues) }));
const avgScore = scores.reduce((sum, s) => sum + s.score, 0) / scores.length;
const hasCritical = allIssues.some(i => i.level === 'critical');
const passed = !hasCritical && scores.every(s => s.score >= 80) && avgScore >= 80;

// QA 통과 여부 결정: passed이거나 최대 재시도 도달 시 통과
const qaPass = passed || qaAttempt >= MAX_QA_RETRIES;

// QA 피드백 생성 (재시도용)
const qaFeedbackText = allIssues
  .filter(i => i.level === 'critical' || i.level === 'warning')
  .map(i => `[${i.level}][${i.agent}] ${i.msg}`)
  .join('\n');

article._qa = {
  passed,
  attempt: qaAttempt,
  avgScore: Math.round(avgScore),
  scores,
  issues: passed ? [] : allIssues.map(i => `[${i.level}][${i.agent}] ${i.msg}`),
};

return [{
  json: {
    article,
    player,
    collected: player.collected,
    qaFeedback: qaFeedbackText,
    qaAttempt,
    qaPass,
  }
}];

// ============================================
// JSON 파일 저장 (v2 - QA 루프 래퍼 지원)
// 개별 JSON + 통합 articles.json 배열
// ============================================

const fs = require('fs');
const _input = $input.first().json;
const article = _input.article || _input;
const dir = '/tmp/kfn-articles';

// 디렉토리 생성
if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
}

// 개별 파일 저장
const individualPath = `${dir}/${article.id}.json`;
fs.writeFileSync(individualPath, JSON.stringify(article, null, 2));

// 통합 배열 업데이트
const allPath = `${dir}/articles.json`;
let all = [];
if (fs.existsSync(allPath)) {
  try {
    all = JSON.parse(fs.readFileSync(allPath, 'utf-8'));
  } catch (e) {
    all = [];
  }
}

// 같은 선수의 이전 기사 교체 (최신만 유지)
all = all.filter(a => a.playerNameKr !== article.playerNameKr);
all.push(article);
all.sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());
fs.writeFileSync(allPath, JSON.stringify(all, null, 2));

return [{
  json: {
    saved: article.id,
    playerNameKr: article.playerNameKr,
    qaPass: article._qa?.passed || false,
    qaAttempt: article._qa?.attempt || 1,
    totalArticles: all.length,
    filePath: individualPath,
  },
}];

// ============================================
// 검색 프롬프트 빌드
// OpenAI Responses API (web_search_preview) 요청 생성
// 초회: 일반 검색 / 재시도: 부족한 소스 보강
// ============================================

const input = $input.first().json;

// 재시도인 경우 player, attempt, accumulated가 이미 포함
const player = input.player || input;
const attempt = (input.attempt || 0) + 1;
const accumulated = input.accumulated || null;

const MAX_ATTEMPTS = 3;
const MIN_NEWS = 3;
const MIN_REDDIT = 2;

// 검색 프롬프트 생성
let searchPrompt;

if (!accumulated) {
  // 초회 검색
  const subs = (player.subreddits || []).map(s => 'r/' + s).join(', ');
  searchPrompt = `Search for recent English-language news and fan reactions about Korean footballer ${player.nameKr} (${player.fotmobName}) at ${player.team} (${player.league}).

FOCUS ON:
1. English-language sports media coverage (BBC Sport, The Guardian, ESPN, The Athletic, transfermarkt, etc.) - recent match reports, transfer news, injury updates, tactical analysis
2. Reddit fan discussions (r/soccer, ${subs}) - fan opinions, match threads, player ratings, top comments with context
3. Fan sentiment and notable quotes from social media

DO NOT include Korean-language sources.
Include source URLs for every item found.
For Reddit: include subreddit name, post title, top comments, upvote context.

Search for: ${player.searchQueries.googleNews}`;
} else {
  // 재시도 검색 - 부족한 소스에 집중
  const newsCount = accumulated.newsSources ? accumulated.newsSources.length : 0;
  const redditCount = accumulated.redditSources ? accumulated.redditSources.length : 0;
  const focusAreas = [];
  if (newsCount < MIN_NEWS) focusAreas.push(`news articles (currently ${newsCount}, need ${MIN_NEWS})`);
  if (redditCount < MIN_REDDIT) focusAreas.push(`Reddit discussions (currently ${redditCount}, need ${MIN_REDDIT})`);

  searchPrompt = `Previous search found ${newsCount} news articles and ${redditCount} Reddit discussions about ${player.nameKr} (${player.fotmobName}).
We need at least ${MIN_NEWS} news + ${MIN_REDDIT} Reddit sources.
Focus more on: ${focusAreas.join(' and ')}.

Try alternative search terms:
- Full name variations: ${player.searchQueries.googleNews}
- Team context: "${player.team}" + "${player.fotmobName}"
- Recent events: last 3 days

Search for English-language coverage about this Korean footballer at ${player.team} (${player.league}).
Include source URLs for every item found.
For Reddit: include subreddit name, post title, top comments.`;
}

// OpenAI Responses API 요청 바디
const searchRequest = {
  model: "gpt-4o",
  tools: [{
    type: "web_search_preview",
    search_context_size: "high"
  }],
  input: searchPrompt
};

return [{
  json: {
    player,
    searchRequest,
    attempt,
    accumulated
  }
}];

// ============================================
// 검색 결과 파싱 (v2 - 최소 2회 수집 보장)
// Responses API output에서 텍스트 + annotations 추출
// 소스 분류 (news vs reddit) + 임계치 확인
// ============================================

const input = $input.first().json;
const promptData = $('검색 프롬프트 빌드').first().json;
const player = promptData.player;
const attempt = promptData.attempt;
const previousAccumulated = promptData.accumulated;

const MIN_NEWS = 3;
const MIN_REDDIT = 2;
const MAX_ATTEMPTS = 3;
const MIN_ATTEMPTS = 2; // 최소 2회 수집 보장

// Responses API 응답에서 텍스트와 annotations 추출
let fullText = '';
const allAnnotations = [];

const output = input.output || [];
for (const item of output) {
  if (item.type === 'message' && item.content) {
    for (const block of item.content) {
      if (block.type === 'output_text') {
        fullText += (block.text || '') + '\n';
        if (block.annotations) {
          allAnnotations.push(...block.annotations);
        }
      }
    }
  }
}

// annotations에서 URL citation 분류
const newsSources = [];
const redditSources = [];

for (const ann of allAnnotations) {
  if (ann.type === 'url_citation' && ann.url) {
    const source = {
      url: ann.url,
      title: ann.title || '',
    };

    if (ann.url.includes('reddit.com')) {
      if (!redditSources.some(s => s.url === source.url)) {
        redditSources.push({ ...source, type: 'reddit' });
      }
    } else {
      if (!newsSources.some(s => s.url === source.url)) {
        newsSources.push({ ...source, type: 'news' });
      }
    }
  }
}

// 이전 accumulated 데이터와 병합 (재시도 시)
let mergedNews = [...newsSources];
let mergedReddit = [...redditSources];

if (previousAccumulated) {
  const existingNewsUrls = new Set(mergedNews.map(s => s.url));
  for (const prev of (previousAccumulated.newsSources || [])) {
    if (!existingNewsUrls.has(prev.url)) {
      mergedNews.push(prev);
    }
  }

  const existingRedditUrls = new Set(mergedReddit.map(s => s.url));
  for (const prev of (previousAccumulated.redditSources || [])) {
    if (!existingRedditUrls.has(prev.url)) {
      mergedReddit.push(prev);
    }
  }
}

// 이전 webSearchSummary 병합
let mergedSummary = fullText.trim();
if (previousAccumulated && previousAccumulated.webSearchSummary) {
  mergedSummary = previousAccumulated.webSearchSummary + '\n\n--- 추가 검색 결과 ---\n\n' + mergedSummary;
}

// 임계치 확인: 최소 2회 수집 보장 + 소스 임계치
const sourcesMet = mergedNews.length >= MIN_NEWS && mergedReddit.length >= MIN_REDDIT;
const meetsThreshold =
  (sourcesMet && attempt >= MIN_ATTEMPTS) ||
  attempt >= MAX_ATTEMPTS;

return [{
  json: {
    player,
    collected: {
      webSearchSummary: mergedSummary,
      newsSources: mergedNews,
      redditSources: mergedReddit,
      totalItems: mergedNews.length + mergedReddit.length,
    },
    attempt,
    meetsThreshold,
    accumulated: {
      newsSources: mergedNews,
      redditSources: mergedReddit,
      webSearchSummary: mergedSummary,
    }
  }
}];

// ============================================
// 검증 프롬프트 빌드
// 수집 데이터 품질 검증 요청 (OpenAI Chat Completions)
// ============================================

const input = $input.first().json;
const player = input.player;
const collected = input.collected;

const sourcesJson = JSON.stringify({
  newsSources: collected.newsSources,
  redditSources: collected.redditSources,
}, null, 2);

const validationPrompt = `You are a data quality validator for a Korean football news platform.
Review the following collected data about ${player.nameKr} (${player.fotmobName}) at ${player.team} (${player.league}) and validate:

1. RELEVANCE: Is each source actually about this specific player? Remove false positives (e.g., different person with similar name).
2. RECENCY: Is the information from the last 3 days?
3. LOCAL OPINION: Is this from overseas/international sources (not Korean media)?
4. FACTUAL ACCURACY: Flag any obvious factual errors.
5. RICHNESS: Rate the overall data quality for article generation (1-10).

Collected sources:
${sourcesJson}

Web search summary (first 3000 chars):
${(collected.webSearchSummary || '').substring(0, 3000)}

Return JSON: {
  "validatedSources": [{ "url": "...", "title": "...", "type": "news|reddit", "isRelevant": true/false, "reason": "..." }],
  "overallQuality": 1-10,
  "hasSufficientData": true/false,
  "summary": "brief quality assessment"
}`;

const validationRequest = {
  model: "gpt-4o",
  messages: [
    { role: "user", content: validationPrompt }
  ],
  response_format: { type: "json_object" },
  temperature: 0.2,
  max_tokens: 4096
};

return [{
  json: {
    player,
    collected,
    validationRequest
  }
}];

// ============================================
// 검증 결과 파싱
// 검증 결과 -> 필터링된 collected 데이터 생성
// ============================================

const input = $input.first().json;
const prevData = $('검증 프롬프트 빌드').first().json;
const player = prevData.player;
const collected = prevData.collected;

// 검증 결과 파싱
let validation;
try {
  const rawContent = input.choices[0].message.content;
  validation = JSON.parse(rawContent);
} catch (error) {
  // 검증 파싱 실패 시 원본 데이터 그대로 통과
  validation = {
    validatedSources: [],
    overallQuality: 5,
    hasSufficientData: true,
    summary: 'Validation parsing failed, using original data'
  };
}

// isRelevant=true인 소스만 필터링
const validatedUrls = new Map();
for (const src of (validation.validatedSources || [])) {
  validatedUrls.set(src.url, src.isRelevant !== false);
}

// 검증된 소스만 필터링 (검증 결과에 없는 소스는 통과)
const validatedNews = collected.newsSources.filter(s =>
  !validatedUrls.has(s.url) || validatedUrls.get(s.url)
);
const validatedReddit = collected.redditSources.filter(s =>
  !validatedUrls.has(s.url) || validatedUrls.get(s.url)
);

return [{
  json: {
    ...player,
    collected: {
      webSearchSummary: collected.webSearchSummary,
      sources: [...validatedNews, ...validatedReddit],
      newsSources: validatedNews,
      redditSources: validatedReddit,
      validation: {
        quality: validation.overallQuality || 5,
        hasSufficientData: validation.hasSufficientData !== false,
        summary: validation.summary || ''
      },
      collectedAt: new Date().toISOString(),
      totalItems: validatedNews.length + validatedReddit.length
    }
  }
}];

// ============================================
// 스탯 데이터 병합
// KFN API에서 조회한 선수 프로필/주간 스탯을
// player 객체에 병합하여 GPT 프롬프트에 전달
// ============================================

// 원본 선수 + collected 데이터 (검증 결과 파싱 출력)
const playerData = $('검증 결과 파싱').first().json;

// 프로필 API 응답 처리
let profileData = null;
try {
  const profileResponse = $('프로필 API 조회').first().json;
  if (profileResponse && profileResponse.data) {
    profileData = profileResponse.data;
  }
} catch (e) {
  // API 실패 시 무시 — 스탯 없이 기사 생성 가능
}

// 주간 스탯 API 응답 처리
let weeklyStats = null;
try {
  const statsResponse = $('주간 스탯 API 조회').first().json;
  if (statsResponse && statsResponse.data && Array.isArray(statsResponse.data)) {
    weeklyStats = statsResponse.data.find(
      s => String(s.player_id) === String(playerData.id)
    );
  }
} catch (e) {
  // API 실패 시 무시
}

// 최근 경기 데이터 파싱 (주간 스탯에 JSON 문자열로 포함)
let recentMatches = [];
if (weeklyStats && weeklyStats.recent_matches_json) {
  try {
    const parsed = JSON.parse(weeklyStats.recent_matches_json);
    if (Array.isArray(parsed)) {
      recentMatches = parsed.slice(0, 5);
    }
  } catch (e) {
    // 파싱 실패 무시
  }
}

// statsData 병합
const statsData = {
  profile: profileData,
  weeklyStats: weeklyStats,
  recentMatches: recentMatches,
  hasData: !!(profileData || weeklyStats),
};

return [{
  json: {
    ...playerData,
    statsData,
  }
}];
